"""Build local classic-script assets from pinned repository source data."""

import argparse
import gzip
import hashlib
import json
from pathlib import Path

APP = Path(__file__).resolve().parent
ROOT = APP.parents[2]
PACKAGE = ROOT / "src/digitalmodel/marine_ops/artificial_lift/dynacard"
RESULTS = ROOT / "docs/domains/artificial_lift/dynacard-examples/results.json"


MODEL_FILES = (("context", "dynacard_classifier.json"), ("shape", "dynacard_shape_classifier.json.gz"))
# Each generated file stays below check-added-large-files --maxkb=1000
# (1,024,000 bytes) with margin, so the models are split into part scripts.
PART_BYTES = 900_000
PART_PATTERN = "models-part-*.js"


def read_model(path):
    """Inference JSON bytes; gzip storage is decompressed as diagnostics.read_model_bytes does."""
    raw = path.read_bytes()
    return gzip.decompress(raw) if path.suffix == ".gz" else raw


def build_examples():
    """Consume the committed results basis, surface cards and source metadata."""
    data = RESULTS.read_bytes()
    document = json.loads(data)
    keys = ("index", "slug", "english_gloss", "source_label", "crosswalk_mode",
            "crosswalk_kind", "source_doi", "dataset_url", "file_url",
            "sheet_name", "licence", "retrieval_date")
    examples = []
    for record in document["examples"]:
        example = {key: record[key] for key in keys}
        example.update(name=record["english_gloss"], card=record["surface_card"],
                       source="https://doi.org/" + record["source_doi"],
                       crosswalk_status=("ASSUMED" if record["crosswalk_kind"] == "assumed" else record["crosswalk_kind"]))
        examples.append(example)
    return {"well": document["basis"]["well"]["value"], "examples": examples,
            "provenance": {"results_path": RESULTS.relative_to(ROOT).as_posix(),
                           "results_sha256": hashlib.sha256(data).hexdigest(),
                           "source": document["source"], "basis": document["basis"],
                           "units": {"position": "in", "load": "lbf"}}}


def script(global_name, body):
    return ("// Generated by build_assets.py; do not hand-edit.\n"
            "(function(root) {\n'use strict';\nconst data = " + body + ";\n"
            f"root.{global_name} = data;\n"
            "if (typeof module === 'object' && module.exports) module.exports = data;\n"
            "}(typeof globalThis !== 'undefined' ? globalThis : this));\n")


def split_literals(text, budget):
    """Cut text into JSON string literals of at most budget bytes, in order."""
    literals, start = [], 0
    while start < len(text):
        end = min(len(text), start + budget)
        while len(literal := json.dumps(text[start:end])) > budget:
            end = start + (end - start) * 9 // 10
        literals.append(literal)
        start = end
    return literals


def part_script(index, count, literal):
    return (f"// Generated by build_assets.py; do not hand-edit. Model part {index} of {count}.\n"
            "(function(root) {\n'use strict';\nconst part = " + literal + ";\n"
            f"(root.DynacardModelParts = root.DynacardModelParts || {{}})[{index}] = part;\n"
            "if (typeof module === 'object' && module.exports) module.exports = part;\n"
            "}(typeof globalThis !== 'undefined' ? globalThis : this));\n")


def loader_script(count, length):
    """models.js joins the part scripts loaded before it and parses the models."""
    return ("// Generated by build_assets.py; do not hand-edit.\n"
            "// Joins models-part-1.js .. models-part-N.js, which load before this file.\n"
            "(function(root) {\n'use strict';\n"
            f"const PART_COUNT = {count};\nconst TEXT_LENGTH = {length};\n"
            "const node = typeof module === 'object' && module.exports;\n"
            "const parts = [];\n"
            "for (let i = 1; i <= PART_COUNT; i++) {\n"
            "  let part = (root.DynacardModelParts || {})[i];\n"
            "  if (node && typeof part !== 'string') {\n"
            "    try { part = require('./models-part-' + i + '.js'); } catch (error) { part = undefined; }\n"
            "  }\n"
            "  if (typeof part !== 'string') {\n"
            "    throw new Error('Dynacard model part ' + i + ' of ' + PART_COUNT + ' is missing.');\n"
            "  }\n"
            "  parts.push(part);\n"
            "}\n"
            "delete root.DynacardModelParts;\n"
            "const text = parts.join('');\n"
            "if (text.length !== TEXT_LENGTH) throw new Error('Dynacard model parts are incomplete.');\n"
            "const data = JSON.parse(text);\n"
            "root.DynacardModels = data;\n"
            "if (node) module.exports = data;\n"
            "}(typeof globalThis !== 'undefined' ? globalThis : this));\n")


def model_assets(models):
    """Compact model JSON split into part scripts plus the models.js loader."""
    text = json.dumps(models, separators=(",", ":"), ensure_ascii=False, allow_nan=False)
    literals = split_literals(text, PART_BYTES)
    assets = {f"models-part-{i}.js": part_script(i, len(literals), literal)
              for i, literal in enumerate(literals, start=1)}
    assets["models.js"] = loader_script(len(literals), len(text))
    return assets


def generated_assets():
    examples = build_examples()
    # Compact serialization preserves every parsed model value without pruning.
    models = {}
    for key, filename in MODEL_FILES:
        models[key] = json.loads(read_model(PACKAGE / "data" / filename))
    first = examples["examples"][0]["card"]
    template = ("# position_in (in), load_lbf (lbf); one full stroke; uniformly timed samples; start anywhere\n"
                "position_in,load_lbf\n")
    template += "".join(f"{x!r},{y!r}\n" for x, y in
                        zip(first["position"], first["load"], strict=True))
    return {**model_assets(models),
            "examples.js": script("DynacardExamples", json.dumps(examples, ensure_ascii=False,
                                                                 indent=2, allow_nan=False)),
            "template.csv": template}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    mismatches = []
    assets = generated_assets()
    for stale in sorted(APP.glob(PART_PATTERN)):
        if stale.name not in assets:
            if args.check:
                mismatches.append(stale.name)
            else:
                stale.unlink()
    for name, content in assets.items():
        target = APP / name
        data = content.encode("utf-8")
        if args.check:
            if not target.exists() or target.read_bytes() != data:
                mismatches.append(name)
        else:
            target.write_bytes(data)
            if target.read_bytes() != data:
                raise OSError(f"Asset readback failed: {name}")
    if mismatches:
        parser.exit(1, "Assets differ: " + ", ".join(mismatches) + "\n")
    print("Assets match source build." if args.check else "Built models.js and its parts, examples.js, template.csv.")


if __name__ == "__main__":
    main()
